  'axt.Proposal': r'''
{
  "type": "record",
  "name": "Proposal",
  "namespace": "axt",
  "doc": "The body of a PROPOSAL message: a receiver of a record proposes changed values of some of its fields to the record's sender, whose user takes or refuses them. Defined in spec/shares.md. The envelope's record field names the sender's record and the version of it that the proposer holds; no version rule applies to the message. The proposal changes nothing by itself: a value the sender's user takes reaches every receiver as an ordinary update. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "ProposalTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the device of the record's sender that the proposal is sent to, a current key of that sender. A device that gets it directly ignores a PROPOSAL that names another key; a forwarded one is rejected unless this is a current or a removed key of the device's own set."
    },
    {
      "name": "proposal_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the proposal, a version 4 or 7 UUID in its 36-character lower-case text form, which the proposer never uses for another proposal and which is not the id of a record, an offer, a request or a forward. The reply to the proposal names it."
    },
    {
      "name": "fields",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "ProposalField",
          "doc": "The proposed value of one top-level field of the record. Defined in spec/shares.md, section 13.1.",
          "fields": [
            {
              "name": "name",
              "type": "string",
              "doc": "The name of the field, as the writer schema named in schema has it."
            },
            {
              "name": "schema",
              "type": {
                "type": "fixed",
                "name": "ProposalFieldSchema",
                "size": 8,
                "doc": "The CRC-64-AVRO fingerprint of a schema, as 8 bytes in little-endian order. Defined in spec/envelope.md, section 5."
              },
              "doc": "The fingerprint of the writer schema of the record's type with which the proposer wrote the value: the writer schema of the record's kept DATA, with which the proposer's change of the field was written. The owner keeps the writer schemas of the DATA it sent to the receiver."
            },
            {
              "name": "value",
              "type": "bytes",
              "doc": "The proposed value of the field, in Avro binary encoding under the type the field has in the schema named in schema."
            }
          ]
        }
      },
      "doc": "The proposed values, 1 to 4096, each field name at most once, in any order. Only fields that the proposal changes; a proposal neither creates nor deletes a record."
    }
  ]
}
''',
  'axt.ProposalReply': r'''
{
  "type": "record",
  "name": "ProposalReply",
  "namespace": "axt",
  "doc": "The body of a PROPOSAL_REPLY message: the answer of a record's sender to one proposal, taken or refused by its user. Defined in spec/shares.md. The envelope's record field is that of the proposal. The reply is a status only: a proposal that is taken reaches the proposer as an ordinary update of the record. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "ProposalReplyTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key that signed the proposal, the key of the proposer's device that sent it. A device ignores a reply that names another key."
    },
    {
      "name": "proposal_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the proposal this message answers, as the proposal carried it."
    },
    {
      "name": "answer",
      "type": {
        "type": "enum",
        "name": "ProposalReplyAnswer",
        "doc": "What the sender's user did with the proposal. ACCEPTED: took every proposed value into the record, which reaches the proposer as an update. DECLINED: did not take the proposal as it stands. The default is for schema resolution only; within one envelope format every symbol is known.",
        "symbols": [
          "ACCEPTED",
          "DECLINED"
        ],
        "default": "DECLINED"
      },
      "doc": "The answer to the proposal."
    }
  ]
}
''',
  'axt.QrPayload': r'''
{
  "type": "record",
  "name": "QrPayload",
  "namespace": "axt",
  "doc": "What a QR code shown by an app carries: its signing key, how to reach it on the local network and through a relay, and whether the code is for adding a device to the sender of the device that shows it. Defined in spec/transports.md. It is not a message and is not signed; scanning it in person confirms the key. Its schema changes only with a new payload version.",
  "fields": [
    {
      "name": "signing_key",
      "type": {
        "type": "fixed",
        "name": "QrPayloadSigningKey",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the installation that shows the code, the sender of every message it sends."
    },
    {
      "name": "encryption_key",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "QrPayloadEncryptionKey",
          "size": 32,
          "doc": "An X25519 public key in the encoding of RFC 7748. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The X25519 public key with which other apps encrypt messages to the installation through a relay. Null when the code names no relay; it is present exactly when relay is."
    },
    {
      "name": "local",
      "type": [
        "null",
        {
          "type": "record",
          "name": "QrPayloadLocal",
          "doc": "Where the installation listens on the local network while it shows the code.",
          "fields": [
            {
              "name": "addresses",
              "type": {
                "type": "array",
                "items": "bytes"
              },
              "doc": "One to four IP addresses of the installation, each 4 bytes for IPv4 or 16 bytes for IPv6, in network byte order, in the order in which a scanner tries them."
            },
            {
              "name": "port",
              "type": "int",
              "doc": "The TCP port on which the installation listens, 1 to 65535."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Where to connect on the local network. Null when the installation does not listen."
    },
    {
      "name": "relay",
      "type": [
        "null",
        {
          "type": "record",
          "name": "QrPayloadRelay",
          "doc": "The relay and the mailbox at it into which other apps put messages for the installation, as in the field relay of axt.Manifest.",
          "fields": [
            {
              "name": "url",
              "type": "string",
              "doc": "The base URL of the relay: an absolute https URL with a host, ending with a slash, without user information, query or fragment, at most 256 bytes."
            },
            {
              "name": "mailbox",
              "type": {
                "type": "fixed",
                "name": "QrPayloadRelayMailbox",
                "size": 32,
                "doc": "A mailbox id. Defined in spec/transports.md."
              },
              "doc": "The id of the mailbox at the relay into which other apps put messages for the installation."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Where to put messages for the installation through a relay. Null when the code names no relay; it is present exactly when encryption_key is."
    },
    {
      "name": "join",
      "type": "boolean",
      "default": false,
      "doc": "True when the code is shown to a new device of the same owner, which scans it to join the devices of the sender, as spec/keys.md, section 5.2, defines; local is then present. False for a code shown to another app."
    }
  ]
}
''',
